#include "ifc3d_internal.h"

typedef struct ifc3d_name_type_s { const char *name; int type; } ifc3d_name_type;

static const ifc3d_name_type g_types[] = {
    {"IFCCARTESIANPOINT", IFC3D_T_IFCCARTESIANPOINT},
    {"IFCDIRECTION", IFC3D_T_IFCDIRECTION},
    {"IFCAXIS2PLACEMENT3D", IFC3D_T_IFCAXIS2PLACEMENT3D},
    {"IFCAXIS2PLACEMENT2D", IFC3D_T_IFCAXIS2PLACEMENT2D},
    {"IFCLOCALPLACEMENT", IFC3D_T_IFCLOCALPLACEMENT},
    {"IFCPOLYLINE", IFC3D_T_IFCPOLYLINE},
    {"IFCPOLYLOOP", IFC3D_T_IFCPOLYLOOP},
    {"IFCFACEOUTERBOUND", IFC3D_T_IFCFACEOUTERBOUND},
    {"IFCFACEBOUND", IFC3D_T_IFCFACEBOUND},
    {"IFCFACE", IFC3D_T_IFCFACE},
    {"IFCCLOSEDSHELL", IFC3D_T_IFCCLOSEDSHELL},
    {"IFCFACETEDBREP", IFC3D_T_IFCFACETEDBREP},
    {"IFCCARTESIANPOINTLIST3D", IFC3D_T_IFCCARTESIANPOINTLIST3D},
    {"IFCTRIANGULATEDFACESET", IFC3D_T_IFCTRIANGULATEDFACESET},
    {"IFCARBITRARYCLOSEDPROFILEDEF", IFC3D_T_IFCARBITRARYCLOSEDPROFILEDEF},
    {"IFCRECTANGLEPROFILEDEF", IFC3D_T_IFCRECTANGLEPROFILEDEF},
    {"IFCCIRCLEPROFILEDEF", IFC3D_T_IFCCIRCLEPROFILEDEF},
    {"IFCEXTRUDEDAREASOLID", IFC3D_T_IFCEXTRUDEDAREASOLID},
    {"IFCSHAPEREPRESENTATION", IFC3D_T_IFCSHAPEREPRESENTATION},
    {"IFCPRODUCTDEFINITIONSHAPE", IFC3D_T_IFCPRODUCTDEFINITIONSHAPE},
    {"IFCBUILDINGELEMENTPROXY", IFC3D_T_IFCBUILDINGELEMENTPROXY},
    {"IFCWALL", IFC3D_T_IFCWALL},
    {"IFCWALLSTANDARDCASE", IFC3D_T_IFCWALLSTANDARDCASE},
    {"IFCSLAB", IFC3D_T_IFCSLAB},
    {"IFCBEAM", IFC3D_T_IFCBEAM},
    {"IFCCOLUMN", IFC3D_T_IFCCOLUMN},
    {"IFCDOOR", IFC3D_T_IFCDOOR},
    {"IFCWINDOW", IFC3D_T_IFCWINDOW},
    {"IFCSTAIR", IFC3D_T_IFCSTAIR},
    {"IFCMEMBER", IFC3D_T_IFCMEMBER},
    {"IFCPLATE", IFC3D_T_IFCPLATE},
    {(const char *)0, 0}
};

int ifc3d_type_from_name(const char *name)
{
    int i;
    for (i = 0; g_types[i].name; ++i) if (ifc3d_strieq(name, g_types[i].name)) return g_types[i].type;
    return IFC3D_T_UNKNOWN;
}

const char *ifc3d_entity_type_name(int t)
{
    int i;
    for (i = 0; g_types[i].name; ++i) if (g_types[i].type == t) return g_types[i].name;
    return "UNKNOWN";
}
